import{_ as e,o as r,c as o,ae as a}from"./chunks/framework.BX6FPmO9.js";const g=JSON.parse('{"title":"是否升級到 React Router v7（Remix 演進）— 討論摘要","description":"","frontmatter":{},"headers":[],"relativePath":"adr/upgrade-v7-discussion.md","filePath":"adr/upgrade-v7-discussion.md"}'),i={name:"adr/upgrade-v7-discussion.md"};function d(n,t,s,l,c,u){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="是否升級到-react-router-v7-remix-演進-—-討論摘要" tabindex="-1">是否升級到 React Router v7（Remix 演進）— 討論摘要 <a class="header-anchor" href="#是否升級到-react-router-v7-remix-演進-—-討論摘要" aria-label="Permalink to &quot;是否升級到 React Router v7（Remix 演進）— 討論摘要&quot;">​</a></h1><p><strong>類型</strong>：adr | <strong>權重</strong>：2</p><p>本文件整理「要不要升級到 v7」的考量，供團隊討論與決策。<strong>非正式 ADR</strong>，僅為討論用。</p><hr><h2 id="_1-「v7」指的是什麼" tabindex="-1">1. 「v7」指的是什麼？ <a class="header-anchor" href="#_1-「v7」指的是什麼" aria-label="Permalink to &quot;1. 「v7」指的是什麼？&quot;">​</a></h2><ul><li><strong>現況</strong>：專案使用 <strong>Remix v2</strong>（<code>@remix-run/*</code> ^2.17.2），底層是 React Router v6。</li><li><strong>v7</strong>：<strong>React Router v7</strong> = Remix 團隊將 Remix 併入 React Router 後的下一版；路由、data loading、actions 等概念延續，但套件與部分 API 會變。</li><li>因此「升級到 v7」= 從 <strong>Remix v2 遷移到 React Router v7</strong>（即「Remix 作為 React Router 的完整版」）。</li></ul><hr><h2 id="_2-目前專案與-v7-的關係" tabindex="-1">2. 目前專案與 v7 的關係 <a class="header-anchor" href="#_2-目前專案與-v7-的關係" aria-label="Permalink to &quot;2. 目前專案與 v7 的關係&quot;">​</a></h2><ul><li>已啟用部分 <strong>v3 future flags</strong>（<code>v3_fetcherPersist</code>、<code>v3_relativeSplatPath</code>、<code>v3_throwAbortReason</code>），有助之後貼近 v7 行為。</li><li>架構（五層、契約、paths、MSW）與框架版本無強綁定，遷移時多數可保留。</li><li>會受影響的：套件名與版號、route 慣例、loader/action 簽名、ESLint（<code>@remix-run/eslint-config</code> 在 v7 不再內建）、部分 Remix 專屬 API。</li></ul><hr><h2 id="_3-升級的好處" tabindex="-1">3. 升級的好處 <a class="header-anchor" href="#_3-升級的好處" aria-label="Permalink to &quot;3. 升級的好處&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面向</th><th>說明</th></tr></thead><tbody><tr><td>長期維護</td><td>走在官方主線，避免停在 v2 後只剩社群修補。</td></tr><tr><td>新功能</td><td>Single Fetch、lazy route discovery 等可選用，有助效能與體積。</td></tr><tr><td>警告與棄用</td><td>不再看到「eslint-config 棄用」「v3_xxx future」等提示（改為預設或移除）。</td></tr><tr><td>文件與生態</td><td>文件與範例會逐漸以 React Router v7 為主。</td></tr></tbody></table><hr><h2 id="_4-暫不升級或延後的理由" tabindex="-1">4. 暫不升級或延後的理由 <a class="header-anchor" href="#_4-暫不升級或延後的理由" aria-label="Permalink to &quot;4. 暫不升級或延後的理由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面向</th><th>說明</th></tr></thead><tbody><tr><td>穩定性與時程</td><td>v7 正式版推出時程與成熟度需確認；若專案以穩定交付為先，可等 v7 穩定一陣再評估。</td></tr><tr><td>遷移成本</td><td>需換套件、改 import、可能動到 route 結構與 loader/action；測試與 CI 要重跑一輪。</td></tr><tr><td>效益是否急迫</td><td>若目前無效能或功能痛點，延後升級可把時間用在產品功能或架構優化。</td></tr><tr><td>依賴相容性</td><td><code>remix-utils</code>、其他 Remix 生態套件是否已支援 v7，需逐項查。</td></tr></tbody></table><hr><h2 id="_5-若升級-預期會動到的部分" tabindex="-1">5. 若升級，預期會動到的部分 <a class="header-anchor" href="#_5-若升級-預期會動到的部分" aria-label="Permalink to &quot;5. 若升級，預期會動到的部分&quot;">​</a></h2><ul><li><strong>package.json</strong>：<code>@remix-run/*</code> → <code>react-router</code> / <code>react-router-dom</code> 等 v7 套件；<code>remix vite:build</code> → 依 v7 官方腳本（如 <code>vite build</code> + 對應 plugin）。</li><li><strong>路由與 entry</strong>：route 慣例、root 與 entry 可能依 v7 模板調整（例如從 Remix 的 <code>app/root.tsx</code> 對應到 v7 的約定）。</li><li><strong>Loader / Action</strong>：簽名或 context 若有 breaking change，需依官方 migration 逐檔調整。</li><li><strong>ESLint</strong>：移除 <code>@remix-run/eslint-config</code>，改用 <a href="./../conventions/eslint-remix-deprecation.html">docs/conventions/eslint-remix-deprecation.md</a> 建議的精簡設定。</li><li><strong>Vitest</strong>：目前已在 test 時停用 Remix plugin；v7 若改為 Vite 為主的 build，可一併確認 test 設定是否仍適用。</li></ul><hr><h2 id="_6-建議的討論問題-供會議或非同步決策" tabindex="-1">6. 建議的討論問題（供會議或非同步決策） <a class="header-anchor" href="#_6-建議的討論問題-供會議或非同步決策" aria-label="Permalink to &quot;6. 建議的討論問題（供會議或非同步決策）&quot;">​</a></h2><ol><li><strong>產品時程</strong>：接下來半年是否有大 release 或上線壓力？若有，是否適合排入「框架升級」？</li><li><strong>v7 狀態</strong>：目前 React Router v7 的 release 狀態與官方 migration guide 是否已足夠清晰？團隊是否有人先做過小規模 PoC？</li><li><strong>優先順序</strong>：在「升級 v7」與「補功能／穩定性／效能（在 v2 上）」之間，哪一項優先？</li><li><strong>試行方式</strong>：是否要開一個分支或小專案，用本專案的架構（paths、contracts、MSW）試遷移一兩個 route，再決定全面升級時程？</li></ol><hr><h2 id="_7-小結" tabindex="-1">7. 小結 <a class="header-anchor" href="#_7-小結" aria-label="Permalink to &quot;7. 小結&quot;">​</a></h2><ul><li><strong>升級 v7</strong>：適合當成「中長期技術債清理 + 跟上主線」，在 v7 穩定、且團隊有餘裕時排期。</li><li><strong>暫不升級</strong>：若目前以交付與穩定為主，留在 Remix v2 並持續用 future flags 與現有架構，是合理選擇；可之後再依 v7 成熟度與官方 migration 重新評估。</li><li>不論是否升級，<strong>契約、paths、MSW、docs 架構</strong>都可維持，遷移時主要對齊新套件與 route/loader API 即可。</li></ul><hr><p><strong>後續</strong>：若討論後有結論，可另寫一則正式 ADR（例如 <code>ADR-001-remix-v2-vs-v7.md</code>）記錄決策與理由。</p>',26)])])}const v=e(i,[["render",d]]);export{g as __pageData,v as default};
